import{_ as a,o,c as d,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const P=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/File-Handles.md","filePath":"manual-zh/File-Handles.md","lastUpdated":1785684581000}'),t={name:"manual-zh/File-Handles.md"};function E(r,e,l,m,p,s){return o(),d("div",null,[...e[0]||(e[0]=[c('<h3 id="_6-9-文件句柄" tabindex="-1">6.9 文件句柄 <a class="header-anchor" href="#_6-9-文件句柄" aria-label="Permalink to &quot;6.9 文件句柄&quot;">​</a></h3><p><em>文件句柄</em> 是对数据文件、系统文件或便携文件的引用。最常见的情况是，文件句柄被指定为字符串形式的文件名，即用 ‘&#39;’ 或 ‘&quot;’ 括起来。</p><p>以 ‘|’ 开头或结尾的文件名字符串被视为向其中传送数据或从中传送数据的命令名称。您可以使用此功能，通过诸如 ‘curl’ 这样的程序通过网络读取数据（<em>例如</em> <code>GET &#39;|curl -s -S http://example.com/mydata.sav&#39;</code>），通过诸如 ‘zcat’ 这样的程序从文件读取压缩数据（<em>例如</em> <code>GET &#39;|zcat mydata.sav.gz&#39;</code>），以及用于许多其他目的。</p><p>PSPP 还支持使用 <code>FILE HANDLE</code> 命令声明命名文件句柄。此命令将您选择的标识符（文件句柄的名称）与文件关联。之后，文件句柄名称可以替代文件名。当 PSPP 语法多次访问一个文件时，声明命名文件句柄可简化日后更新语法以使用不同文件的过程。读取二进制格式的数据文件还需要使用 <code>FILE HANDLE</code>。更多信息请参见 <a href="./FILE-HANDLE">FILE HANDLE</a>。</p><p>在某些情况下，PSPP 必须区分文件句柄是指系统文件还是便携文件。当读取文件需要这样做时，<em>例如</em> 作为 <code>GET</code> 或 <code>MATCH FILES</code> 的输入文件，PSPP 使用文件的内容来判断。在写入文件的上下文中，<em>例如</em> 作为 <code>SAVE</code> 或 <code>AGGREGATE</code> 的输出文件，PSPP 根据文件名判断：如果文件名以 ‘.por’ 结尾（大小写不限），则 PSPP 写入便携文件；否则，PSPP 写入系统文件。</p><p>INLINE 作为文件句柄名被保留。它指嵌入在 <code>BEGIN DATA</code> 和 <code>END DATA</code> 之间语法文件中的“数据文件”。更多信息请参见 <a href="./BEGIN-DATA">BEGIN DATA</a>。</p><p>文件句柄所引用的文件可以在后续的 <code>FILE HANDLE</code> 命令中重新分配，前提是它首先使用 <code>CLOSE FILE HANDLE</code> 关闭。更多信息请参见 <a href="./CLOSE-FILE-HANDLE">CLOSE FILE HANDLE</a>。</p>',7)])])}const A=a(t,[["render",E]]);export{P as __pageData,A as default};
